-- SP-1 · S2 Klartext: Titel aller 47 Bauformen und Beschreibung/Beispiel je Stufe der 41 bestätigten Bauformen.
-- Quelle docs/freigabe/sp1/klartext-entwurf.json, geprüft von einem frischen Subagenten (klartext-pruefung.md).
-- Strittig und deshalb NICHT enthalten (bleiben offen, die Ansicht zeigt dort die Generator-Regel):
--   EIN-1, EX-2, KO-1, NP-4, NS-4, NS-5.
-- Nur Datenänderung an bauformen.titel und bauform_stufen (kein Steckbrief → kein Versionswechsel, Status unverändert).
--
-- Prüfabfrage:
--   select (select count(*) from bauformen where titel is not null) as titel,
--          (select count(*) from bauform_stufen where beschreibung is not null and beispiel is not null) as stufen,
--          (select count(distinct titel) from bauformen) as verschieden,
--          (select string_agg(distinct status, ',') from bauformen) as status,
--          (select max(version) from bauformen) as version;
--   → titel 47, stufen 100, verschieden 47, status zur_pruefung, version 1
update public.bauformen b set titel = v.titel
  from (values
    ('AUS-1', 'Gemeinsamen Faktor ausklammern'),
    ('BIN-1', 'Quadrat einer Klammer ausmultiplizieren'),
    ('BIN-2', 'Term als Klammerquadrat schreiben'),
    ('DI-1', 'Anzahl der Lösungen bestimmen'),
    ('DI-2', 'Begründung wählen: Gleichung ohne Lösung'),
    ('DI-3', 'Zahl für genau eine Lösung finden'),
    ('EIN-1', 'Werte in Terme einsetzen'),
    ('EX-0', 'Höchsten oder tiefsten Wert im Sachkontext bestimmen'),
    ('EX-1', 'Größte Beetfläche bei fester Zaunlänge'),
    ('EX-2', 'Größte Wurfhöhe und Zeitpunkt bestimmen'),
    ('EX-3', 'Größten Gewinn eines Cafés bestimmen'),
    ('GL-1', 'Lineare Gleichung in zwei Schritten lösen'),
    ('KO-1', 'Punkt im Koordinatensystem ablesen'),
    ('NF-1', 'Scheitelpunktform in Normalform umwandeln'),
    ('NF-2', 'Scheitelpunktform per quadratischer Ergänzung bilden'),
    ('NF-3', 'Quadratische Ergänzung mit Zahl vor x²'),
    ('NF-4', 'Schritte der quadratischen Ergänzung ordnen'),
    ('NF-5', 'Fehler in quadratischer Ergänzung finden'),
    ('NF-6', 'Scheitelpunkt aus der Normalform bestimmen'),
    ('NP-1', 'Produkt zweier Klammern gleich null lösen'),
    ('NP-2', 'x ausklammern und Gleichung lösen'),
    ('NP-3', 'Fehler finden: durch x geteilt'),
    ('NP-4', 'Erst umstellen, dann ausklammern und lösen'),
    ('NS-1', 'Nullstellen aus der Scheitelpunktform bestimmen'),
    ('NS-2', 'Nullstellen aus der Normalform bestimmen'),
    ('NS-3', 'Nullstellen aus der Produktform ablesen'),
    ('NS-4', 'Parabel zu gegebenen Nullstellen auswählen'),
    ('NS-5', 'Anzahl der Nullstellen begründen'),
    ('PAR-1', 'Wertetabelle einer Parabel ausfüllen'),
    ('PAR-2', 'Graph zum Streckfaktor auswählen'),
    ('PAR-3', 'Graph zur verschobenen Parabel auswählen'),
    ('PAR-4', 'Gleichung der verschobenen Normalparabel angeben'),
    ('PAR-5', 'Aussagen über zwei Streckfaktoren beurteilen'),
    ('PQ-1', 'Normalform herstellen, p und q ablesen'),
    ('PQ-2', 'Gleichung mit der p-q-Formel lösen'),
    ('PQ-3', 'Fehler im Lösungsweg der p-q-Formel finden'),
    ('PQ-4', 'Schritte der p-q-Formel ordnen'),
    ('QW-1', 'Quadratzahlen und Wurzeln berechnen'),
    ('SCH-1', 'Scheitelpunkt aus der Scheitelpunktform ablesen'),
    ('SCH-2', 'Parabelgleichung aus dem Graphen ablesen'),
    ('SCH-3', 'Hoch- oder Tiefpunkt bestimmen und verorten'),
    ('SCH-4', 'Fehler beim Ablesen des Scheitels finden'),
    ('WZ-1', 'x² gleich Zahl durch Wurzelziehen lösen'),
    ('WZ-2', 'Erst umstellen, dann Wurzel ziehen'),
    ('WZ-3', 'Quadrierte Klammer gleich Zahl lösen'),
    ('WZ-4', 'Begründen, warum x² nicht negativ wird'),
    ('WZ-5', 'Lösungen mit Wurzel angeben')
  ) v(schluessel, titel)
 where b.schluessel = v.schluessel;

update public.bauform_stufen s set beschreibung = v.beschreibung, beispiel = v.beispiel, geaendert_am = now()
  from (values
    ('AUS-1', 1, 'Term aus x² und x ohne gemeinsame Zahl: nur x wird ausgeklammert. Vor x² steht 1 bis 6, vor x eine Zahl von −9 bis 9.', 'Klammere den größten gemeinsamen Faktor aus: x² + 8x.'),
    ('AUS-1', 2, 'Term mit x und einer Zahl; ausgeklammert wird eine Zahl (4, 6, 8, 9, 10 oder 12).', 'Klammere den größten gemeinsamen Faktor aus: 18x − 30.'),
    ('AUS-1', 3, 'Term mit x² und x; ausgeklammert wird eine Zahl mal x (Zahl 4, 6, 8, 9, 10 oder 12).', 'Klammere den größten gemeinsamen Faktor aus: 27x² − 72x.'),
    ('BIN-1', 1, 'Klammer mit Plus: x plus eine Zahl von 1 bis 15, zum Quadrat.', 'Multipliziere (x + 13)² aus.'),
    ('BIN-1', 2, 'Klammer mit Minus: x minus eine Zahl von 1 bis 15, zum Quadrat.', 'Multipliziere (x − 3)² aus.'),
    ('BIN-1', 3, 'Vor x steht eine Zahl (2 bis 5), dahinter minus eine Zahl von 1 bis 9. Auch die Zahl vor x muss quadriert werden.', 'Multipliziere (3x − 2)² aus.'),
    ('BIN-2', 1, 'Plus vor dem x-Glied; in der Klammer steht eine Zahl von 3 bis 15.', 'Schreib x² + 12x + 36 als Quadrat.'),
    ('BIN-2', 2, 'Minus vor dem x-Glied; in der Klammer steht eine Zahl von 3 bis 15.', 'Schreib x² − 16x + 64 als Quadrat.'),
    ('BIN-2', 3, 'Große Zahlen: in der Klammer steht 16 bis 25, mit Plus oder Minus.', 'Schreib x² − 44x + 484 als Quadrat.'),
    ('DI-1', 1, 'Normalform mit 1 vor x². Die Zahl vor x ist gerade (−6 bis 6), die Zahl ohne x liegt zwischen −6 und 6. Keine, eine oder zwei Lösungen kommen gleich oft vor.', 'Wie viele Lösungen hat x² + 2x + 5 = 0?'),
    ('DI-1', 2, 'Normalform mit größeren Zahlen: die gerade Zahl vor x reicht bis ±20, die Zahl ohne x meist von −20 bis 20.', 'Wie viele Lösungen hat x² + 2x + 18 = 0?'),
    ('DI-1', 3, 'Vor x² steht 2, 3 oder 4; die ganze Gleichung ist ein Vielfaches einer Normalform mit Zahlen wie in Stufe 2.', 'Wie viele Lösungen hat 3x² − 6x + 9 = 0?'),
    ('DI-1', 4, 'Die Gleichung steht nicht in Normalform: Die Zahl ohne x steht rechts vom Gleichheitszeichen. Zahlen wie in Stufe 2.', 'Wie viele Lösungen hat x² − 10x = −15?'),
    ('DI-2', 3, 'Normalform ohne Lösung, die Zahl vor x ist gerade (bis ±12), die Zahl ohne x positiv (bis 50). Eine richtige Begründung mit der Rechnung unter der Wurzel, drei falsche.', 'Warum hat x² + 4x + 43 = 0 keine Lösung? Wähle die passende Begründung.'),
    ('DI-3', 4, 'Normalform, die Zahl ohne x fehlt und ist gesucht. Die Zahl vor x ist gerade (−16 bis 16), die Antwort ist eine ganze Zahl.', 'Für welche Zahl q hat x² + 12x + q = 0 genau eine Lösung?'),
    ('DI-3', 5, 'Die Zahl vor x ist ungerade (−15 bis 15), die Antwort ist ein Bruch.', 'Für welche Zahl q hat x² − 15x + q = 0 genau eine Lösung?'),
    ('EX-0', 1, 'Wurf: Höhe in Scheitelpunktform, nach unten geöffnet. Scheitel nach 1 bis 5 Sekunden, Höhe 6 bis 30 m. Drei Teile: wann, wie hoch, größter oder kleinster Wert.', 'Ein Ball wird geworfen. Seine Höhe über dem Boden ist h(t) = −(t − 2)² + 10 (t in Sekunden, h in Metern). Nach wie vielen Sekunden ist der Ball am höchsten? Wie hoch ist er dann? Ist das ein größter oder ein kleinster Wert?'),
    ('EX-0', 2, 'Kosten: Funktion in Scheitelpunktform, nach oben geöffnet. Tiefster Punkt bei 3 bis 12 Kisten, Kosten 5 bis 40 Euro. Drei Teile wie in Stufe 1.', 'Eine Firma stellt x Kisten am Tag her. Die Kosten je Kiste sind K(x) = (x − 5)² + 30 (in Euro). Bei wie vielen Kisten sind die Kosten je Kiste am kleinsten? Wie hoch sind sie dann? Ist das ein größter oder ein kleinster Wert?'),
    ('EX-0', 3, 'Wurf oder Kosten wie in Stufe 1 und 2, aber die Funktion steht in Normalform: erst den Scheitel bestimmen.', 'Eine Firma stellt x Kisten am Tag her. Die Kosten je Kiste sind K(x) = x² − 18x + 105 (in Euro). Bei wie vielen Kisten sind die Kosten je Kiste am kleinsten? Wie hoch sind sie dann? Ist das ein größter oder ein kleinster Wert?'),
    ('EX-1', 4, 'Rechteckiges Beet, ringsum eingezäunt, Zaunlänge 8 bis 80 m (in Viererschritten). Gesucht sind die Seitenlänge x und die größte Fläche; die Lösung ist ein Quadrat.', 'Mit 32 m Zaun soll ein rechteckiges Beet ganz eingezäunt werden. Eine Seite ist x m lang. Wie muss man x wählen, damit die Fläche am größten ist? Gefragt: x in Metern und die größte Fläche in Quadratmetern.'),
    ('EX-1', 5, 'Beet an einer Hauswand, Zaun nur an drei Seiten, Zaunlänge 8 bis 80 m. Gesucht sind x und die größte Fläche.', 'Ein rechteckiges Beet liegt an einer Hauswand. Die anderen drei Seiten bekommen 56 m Zaun. Die beiden Seiten, die von der Wand weggehen, sind je x m lang. Wie muss man x wählen, damit die Fläche am größten ist? Gefragt: x in Metern und die größte Fläche in Quadratmetern.'),
    ('EX-3', 4, 'Gewinnfunktion in Normalform, nach unten geöffnet, vor x² steht −1 oder −2. Größter Gewinn bei 10 bis 60 Stück, 100 bis 900 Euro.', 'Ein Café verkauft x Stücke Kuchen am Tag. Der Gewinn ist G(x) = −2x² + 136x − 2170 (in Euro). Bei welcher Stückzahl ist der Gewinn am größten, und wie groß ist er?'),
    ('GL-1', 1, 'Vor x steht 2 bis 9. Die Lösung ist eine positive ganze Zahl (1 bis 12).', 'Löse 4x − 13 = 23. Gib x an.'),
    ('GL-1', 2, 'Vor x steht 2 bis 9. Die Lösung ist eine negative ganze Zahl (−1 bis −12).', 'Löse 9x − 12 = −30. Gib x an.'),
    ('GL-1', 3, 'Vor x steht 2 bis 9. Die Lösung ist ein gekürzter Bruch, positiv oder negativ.', 'Löse 4x + 9 = −2. Gib x als gekürzten Bruch an.'),
    ('NF-1', 1, 'Keine Zahl vor der Klammer. In der Klammer steht minus eine Zahl (1 bis 9), hinten plus eine Zahl (1 bis 9).', 'Schreib f(x) = (x − 4)² + 6 in der Normalform.'),
    ('NF-1', 2, 'Wie Stufe 1, aber Plus oder Minus in der Klammer und hinten gemischt.', 'Schreib f(x) = (x + 1)² − 5 in der Normalform.'),
    ('NF-1', 3, 'Vor der Klammer steht −2, −1, 2 oder 3; Vorzeichen gemischt. Die Zahl vor der Klammer muss mit allen Gliedern malgenommen werden.', 'Schreib f(x) = 3(x − 9)² − 4 in der Normalform.'),
    ('NF-2', 2, 'Keine Zahl vor x². Die Zahl vor x ist gerade (bis ±10), die Zahl hinten in der Scheitelpunktform ist positiv.', 'Schreib f(x) = x² − 6x + 20 in der Scheitelpunktform.'),
    ('NF-2', 3, 'Die Zahl vor x ist gerade (bis ±16); die Zahl hinten in der Scheitelpunktform kann auch negativ sein.', 'Schreib f(x) = x² − 12x − 2 in der Scheitelpunktform.'),
    ('NF-2', 4, 'Die Zahl vor x ist ungerade (bis ±13): Scheitelkoordinaten sind Brüche.', 'Schreib f(x) = x² + 7x + 22 in der Scheitelpunktform.'),
    ('NF-3', 4, 'Vor x² steht 2 oder 3. Der Scheitel hat ganze Koordinaten (x von −6 bis 6, y von −15 bis 15).', 'Schreib f(x) = 3x² + 6x + 4 in der Scheitelpunktform.'),
    ('NF-3', 5, 'Vor x² steht −2, −1, 4 oder 5. Scheitel ganzzahlig wie in Stufe 4.', 'Schreib f(x) = 5x² + 30x + 44 in der Scheitelpunktform.'),
    ('NF-4', 2, 'Keine Zahl vor x², gerade Zahl vor x. Vier Schritte bis zum Scheitelpunkt; die y-Koordinate des Scheitels ist positiv.', 'Bring die Schritte der quadratischen Ergänzung für f(x) = x² − 2x + 16 in die richtige Reihenfolge.'),
    ('NF-4', 3, 'Wie Stufe 2, aber die y-Koordinate des Scheitels ist negativ.', 'Bring die Schritte der quadratischen Ergänzung für f(x) = x² + 8x + 13 in die richtige Reihenfolge.'),
    ('NF-5', 3, 'Keine Zahl vor x². Im vorgerechneten Weg wurde die Ergänzung nur dazugezählt und nicht wieder abgezogen. Gesucht: falsche Zeile und Begründung.', 'Tom bringt f(x) = x² − 6x + 15 in die Scheitelpunktform. In welcher Zeile steckt der Fehler, und warum?'),
    ('NF-5', 4, 'Vor x² steht 2 oder 3. Im vorgerechneten Weg wurde die abgezogene Ergänzung nicht mit dieser Zahl malgenommen.', 'Ben bringt f(x) = 3x² + 12x + 1 in die Scheitelpunktform. In welcher Zeile steckt der Fehler, und warum?'),
    ('NF-6', 3, 'Keine Zahl vor x², gerade Zahl vor x. Der Scheitel hat ganze Koordinaten (x von −8 bis 8, y von −15 bis 15).', 'Bestimme den Scheitelpunkt von f(x) = x² − 16x + 62.'),
    ('NF-6', 4, 'Vor x² steht −1 oder 2. Scheitel ganzzahlig wie in Stufe 3.', 'Bestimme den Scheitelpunkt von f(x) = 2x² − 12x + 7.'),
    ('NP-1', 1, 'In beiden Klammern steht x minus eine Zahl; beide Lösungen positiv (1 bis 12) und verschieden.', 'Löse (x − 7)(x − 2) = 0.'),
    ('NP-1', 2, 'Eine Klammer mit Plus, eine mit Minus: eine Lösung negativ (−1 bis −12), eine positiv (1 bis 12).', 'Löse (x + 4)(x − 1) = 0.'),
    ('NP-2', 1, 'Keine Zahl vor x², minus eine Zahl vor x (2 bis 20): die zweite Lösung ist positiv.', 'Löse x² − 6x = 0.'),
    ('NP-2', 2, 'Keine Zahl vor x², plus eine Zahl vor x (2 bis 20): die zweite Lösung ist negativ.', 'Löse x² + 6x = 0.'),
    ('NP-2', 3, 'Vor x² steht 2 bis 5; die zweite Lösung ist eine ganze Zahl (±2 bis ±6).', 'Löse 4x² + 8x = 0.'),
    ('NP-2', 4, 'Vor x² steht 2 bis 6; die zweite Lösung ist ein gekürzter Bruch.', 'Löse 3x² − 10x = 0.'),
    ('NP-3', 3, 'Gleichung nur mit x² und x (vor x² 1 bis 4, vor x ±2 bis ±12), rechts steht das x-Glied oder null. Im vorgerechneten Weg wurde durch x geteilt, die Lösung 0 fehlt.', 'Noah hat 2x² = −3x gelöst. In welcher Zeile steckt der Fehler, und warum?'),
    ('NS-1', 2, 'Nach oben geöffnet, keine Zahl vor der Klammer; hinten minus eine Quadratzahl (1 bis 36).', 'Bestimme die Nullstellen von f(x) = (x − 6)² − 4.'),
    ('NS-1', 3, 'Nach unten geöffnet (Minus vor der Klammer); hinten plus eine Quadratzahl (1 bis 36).', 'Bestimme die Nullstellen von f(x) = −(x − 6)² + 9.'),
    ('NS-1', 4, 'Vor der Klammer steht −2 oder 2. Meist zwei Nullstellen, etwa jede vierte Aufgabe hat keine.', 'Bestimme die Nullstellen von f(x) = −2(x + 7)² + 32.'),
    ('NS-2', 3, 'Keine Zahl vor x². Zwei verschiedene ganzzahlige Nullstellen von −9 bis 9.', 'Bestimme die Nullstellen von f(x) = x² − 8x + 15.'),
    ('NS-2', 4, 'Vor x² steht −1, 2 oder 3; Nullstellen ganzzahlig wie in Stufe 3.', 'Bestimme die Nullstellen von f(x) = 2x² − 12x − 54.'),
    ('NS-3', 1, 'Zwei Klammern, keine Zahl davor. Nullstellen von −9 bis 9, verschieden.', 'Bestimme die Nullstellen von f(x) = (x + 5)(x + 4).'),
    ('NS-3', 2, 'Vor den Klammern steht −2, 2 oder 3, oder der Term hat die Form x mal Klammer (dann ist 0 eine Nullstelle).', 'Bestimme die Nullstellen von f(x) = x(x − 9).'),
    ('PAR-1', 1, 'Keine Zahl vor x². Vier x-Werte von −3 bis 3, mindestens zwei davon negativ.', 'Fülle die Wertetabelle für f(x) = x² aus (x = −3, −1, 1, 2).'),
    ('PAR-1', 2, 'Vor x² steht 2 oder 3; x-Werte wie in Stufe 1.', 'Fülle die Wertetabelle für f(x) = 3x² aus (x = −3, −2, −1, 2).'),
    ('PAR-1', 3, 'Vor x² steht −1, −2 oder −3; x-Werte wie in Stufe 1.', 'Fülle die Wertetabelle für f(x) = −2x² aus (x = −3, −2, −1, 2).'),
    ('PAR-1', 4, 'Vor x² steht 1/2 oder 1/4; vier gerade x-Werte von −6 bis 6.', 'Fülle die Wertetabelle für f(x) = 1/2 · x² aus (x = −6, −4, 2, 4).'),
    ('PAR-2', 1, 'Nach oben geöffnet und schmaler als die Normalparabel: vor x² steht 3/2, 2, 5/2, 3 oder 4.', 'Welcher Graph gehört zu f(x) = 4x²? (Drei Parabeln zur Auswahl.)'),
    ('PAR-2', 2, 'Nach oben geöffnet und breiter als die Normalparabel: vor x² steht 1/2, 1/3, 1/4, 2/3 oder 3/4.', 'Welcher Graph gehört zu f(x) = 1/4 · x²? (Drei Parabeln zur Auswahl.)'),
    ('PAR-2', 3, 'Nach unten geöffnet: vor x² steht −1/3, −1/2, −2, −3 oder −4.', 'Welcher Graph gehört zu f(x) = −4x²? (Drei Parabeln zur Auswahl.)'),
    ('PAR-3', 1, 'Nur nach oben oder unten verschoben (um 1 bis 5).', 'Welcher Graph gehört zu f(x) = x² − 3? (Drei Parabeln zur Auswahl.)'),
    ('PAR-3', 2, 'Nur nach links oder rechts verschoben (um 1 bis 5).', 'Welcher Graph gehört zu f(x) = (x + 2)²? (Drei Parabeln zur Auswahl.)'),
    ('PAR-3', 3, 'In beide Richtungen verschoben (je 1 bis 5, verschieden weit).', 'Welcher Graph gehört zu f(x) = (x − 3)² + 2? (Drei Parabeln zur Auswahl.)'),
    ('PAR-4', 2, 'Nach rechts und nach oben verschoben, je um 1 bis 8.', 'Die Normalparabel wird um 2 nach rechts und um 7 nach oben verschoben. Gib die Gleichung der neuen Parabel an.'),
    ('PAR-4', 3, 'Mindestens eine Verschiebung geht nach links oder nach unten (je 1 bis 8).', 'Die Normalparabel wird um 1 nach links und um 3 nach unten verschoben. Gib die Gleichung der neuen Parabel an.'),
    ('PAR-4', 4, 'Wie Stufe 3, dazu vorher mit dem Faktor 2 oder 3 gestreckt oder mit 1/2 gestaucht.', 'Die Normalparabel wird mit dem Faktor 3 gestreckt und dann um 7 nach links und um 5 nach oben verschoben. Gib die Gleichung der neuen Parabel an.'),
    ('PAR-5', 2, 'Zwei Parabeln ohne Verschiebung, beide nach oben geöffnet; vor x² steht 1/4, 1/3, 1/2, 2, 3 oder 4 (verschieden). Vier Aussagen, eine stimmt.', 'Gegeben sind f(x) = 2x² und g(x) = 1/2 · x². Welche Aussage stimmt?'),
    ('PAR-5', 3, 'Wie Stufe 2, aber eine der beiden Parabeln ist nach unten geöffnet.', 'Gegeben sind f(x) = −1/2 · x² und g(x) = 3x². Welche Aussage stimmt?'),
    ('PQ-1', 1, 'Steht schon in Normalform, beide Zahlen positiv.', 'Bring x² + 3x + 7 = 0 in die Form x² + px + q = 0. Gib p und q an.'),
    ('PQ-1', 2, 'Normalform, mindestens eine der beiden Zahlen negativ.', 'Bring x² − 3x + 17 = 0 in die Form x² + px + q = 0. Gib p und q an.'),
    ('PQ-1', 3, 'Vor x² steht 2 bis 5: erst durch diese Zahl teilen. Mindestens eine Zahl wird negativ.', 'Bring 3x² − 27x + 6 = 0 in die Form x² + px + q = 0. Gib p und q an.'),
    ('PQ-1', 4, 'Nicht in Normalform: eine oder zwei Zahlen stehen rechts vom Gleichheitszeichen, erst umstellen.', 'Bring x² = 2x − 19 in die Form x² + px + q = 0. Gib p und q an.'),
    ('PQ-2', 1, 'Normalform, beide Zahlen positiv; zwei ganzzahlige Lösungen.', 'Löse mit der p-q-Formel: x² + 14x + 33 = 0.'),
    ('PQ-2', 2, 'Normalform, mindestens eine Zahl negativ; zwei ganzzahlige Lösungen.', 'Löse mit der p-q-Formel: x² − 3x − 54 = 0.'),
    ('PQ-2', 3, 'Vor x² steht 2 oder 3: erst durch diese Zahl teilen. Zwei ganzzahlige Lösungen.', 'Löse mit der p-q-Formel: 2x² − 26x + 80 = 0.'),
    ('PQ-2', 4, 'Nicht in Normalform: die Zahl ohne x steht rechts, erst umstellen.', 'Löse mit der p-q-Formel: x² + 5x = 36.'),
    ('PQ-3', 3, 'Normalform mit ganzzahligen Lösungen. Der Fehler steckt beim Einsetzen: Vorzeichen vor p/2 oder vor q falsch.', 'Emma löst x² − 6x + 5 = 0 mit der p-q-Formel. In welcher Zeile steckt der Fehler, und warum?'),
    ('PQ-3', 4, 'Der Fehler steckt unter der Wurzel: p/2 nicht quadriert oder die Wurzel falsch gezogen.', 'Emma löst x² + 2x − 99 = 0 mit der p-q-Formel. In welcher Zeile steckt der Fehler, und warum?'),
    ('PQ-4', 2, 'Vor x² steht 2 bis 4; vier Schritte bis zur Lösungsmenge (teilen, einsetzen, Wurzel ziehen, Lösungen). Zwei ganzzahlige Lösungen.', 'Bring die Schritte zum Lösen von 3x² + 6x − 45 = 0 in die richtige Reihenfolge.'),
    ('QW-1', 1, 'Eine Zahl von 3 bis 12 zum Quadrat.', 'Berechne 12².'),
    ('QW-1', 2, 'Wurzel aus einer Quadratzahl von 9 bis 225.', 'Berechne √81.'),
    ('QW-1', 3, 'Eine negative Zahl in Klammern zum Quadrat (−3 bis −20).', 'Berechne (−18)².'),
    ('SCH-1', 1, 'Keine Zahl vor der Klammer; in der Klammer minus, hinten plus, Zahlen 1 bis 9.', 'Gib den Scheitelpunkt von f(x) = (x − 5)² + 2 an.'),
    ('SCH-1', 2, 'In der Klammer minus, hinten minus (Zahlen 1 bis 9).', 'Gib den Scheitelpunkt von f(x) = (x − 3)² − 4 an.'),
    ('SCH-1', 3, 'In der Klammer plus; hinten plus oder minus.', 'Gib den Scheitelpunkt von f(x) = (x + 9)² − 8 an.'),
    ('SCH-1', 4, 'Vor der Klammer steht −3, −2, 2, 3 oder 1/2; Vorzeichen gemischt.', 'Gib den Scheitelpunkt von f(x) = 2(x + 7)² + 6 an.'),
    ('SCH-2', 2, 'Normalparabel, nach oben geöffnet; Scheitel mit ganzen Koordinaten von −4 bis 4 (nicht auf einer Achse).', 'Die Abbildung zeigt eine Parabel. Gib ihre Gleichung in der Scheitelpunktform an. (Figur: Normalparabel nach oben, Scheitel S(3 | −1) markiert.)'),
    ('SCH-2', 3, 'Nach unten geöffnet, so breit wie die Normalparabel; Scheitel wie in Stufe 2.', 'Die Abbildung zeigt eine Parabel. Gib ihre Gleichung in der Scheitelpunktform an. (Figur: Parabel nach unten, Scheitel S(2 | 3) markiert.)'),
    ('SCH-2', 4, 'Gestreckt (Faktor 2) oder gestaucht (Faktor 1/2), nach oben geöffnet; Scheitel wie in Stufe 2.', 'Die Abbildung zeigt eine Parabel. Gib ihre Gleichung in der Scheitelpunktform an. (Figur: Parabel mit Faktor 2, Scheitel S(−1 | 2) markiert.)'),
    ('SCH-3', 2, 'Scheitelpunktform mit 1 oder −1 vor der Klammer; die Zahl hinten hat das andere Vorzeichen als die Zahl vor der Klammer. Zwei Bausteine wählen: Art und Lage.', 'Hat f(x) = −(x + 4)² + 8 einen Hochpunkt oder einen Tiefpunkt, und wo liegt er? Wähle zwei Bausteine.'),
    ('SCH-3', 3, 'Wie Stufe 2, vor der Klammer steht −2, −1/2, 1/2 oder 2.', 'Hat f(x) = −2(x − 4)² + 8 einen Hochpunkt oder einen Tiefpunkt, und wo liegt er? Wähle zwei Bausteine.'),
    ('SCH-4', 3, 'Scheitelpunktform, vor der Klammer −3, −2, 1, 2 oder 3. Im vorgerechneten Ablesen ist ein Fehler: Vorzeichen in der Klammer, Vorzeichen hinten oder die Zahl vor der Klammer als Koordinate.', 'Finn liest den Scheitel von f(x) = 2(x + 6)² + 1 ab. In welcher Zeile steckt der erste Fehler, und warum?'),
    ('WZ-1', 1, 'Rechts steht eine Quadratzahl von 9 bis 400: zwei ganzzahlige Lösungen.', 'Löse x² = 144.'),
    ('WZ-1', 2, 'Rechts steht 0 (eine Lösung) oder eine negative Quadratzahl von −4 bis −100 (keine Lösung).', 'Löse x² = −25.'),
    ('WZ-2', 2, 'Keine Zahl vor x²; nach dem Umstellen steht rechts eine Quadratzahl von 1 bis 144.', 'Löse x² − 24 = 40.'),
    ('WZ-2', 3, 'Vor x² steht 2 bis 5; nach Umstellen und Teilen steht rechts eine Quadratzahl von 1 bis 64.', 'Löse 4x² − 7 = 29.'),
    ('WZ-3', 3, 'In der Klammer steht x minus eine Zahl (1 bis 9); rechts eine Quadratzahl von 1 bis 81.', 'Löse (x − 6)² = 81.'),
    ('WZ-3', 4, 'In der Klammer Plus oder Minus; rechts eine Quadratzahl (bis 100), 0 oder eine negative Zahl (dann keine Lösung).', 'Löse (x + 7)² = 0.'),
    ('WZ-4', 2, 'x² gleich einer negativen Zahl (−1 bis −30). Eine richtige Begründung, drei falsche.', 'Warum hat x² = −14 keine Lösung? Wähle die passende Begründung.'),
    ('WZ-5', 4, 'x² gleich einer Zahl von 2 bis 60, die keine Quadratzahl ist: Lösungen mit Wurzel. Auswahl aus mehreren Antworten.', 'Welche Lösungen hat x² = 42?')
  ) v(schluessel, stufe, beschreibung, beispiel)
  join public.bauformen b on b.schluessel = v.schluessel
 where s.bauform_id = b.id and s.stufe = v.stufe;
